(() => {
  const $=id=>document.getElementById(id);
  const api=async(path,options={})=>{const response=await fetch(path,{cache:'no-store',headers:{accept:'application/json',...(options.body?{'content-type':'application/json'}:{})},...options,body:options.body?JSON.stringify(options.body):undefined});const text=await response.text();let data={};try{data=JSON.parse(text||'{}')}catch{data={ok:false,error:text||'Invalid response'}}if(response.status===401){location.href='/member-login.html';throw new Error('Authentication required')}if(response.status===403){location.href='/access-denied.html?required=admin&current=member';throw new Error('Administrator access required')}if(!response.ok||data.ok===false)throw new Error(data.error||'Request failed');return data};
  const empty=(node,message)=>{node.replaceChildren();const p=document.createElement('p');p.className='muted';p.textContent=message;node.append(p)};
  const textCell=value=>{const td=document.createElement('td');td.textContent=String(value??'');return td};
  function status(message,type=''){const node=$('admin-status');node.className='status '+type;node.textContent=message}
  async function loadSummary(){const data=await api('/api/member/admin/summary');for(const [key,value] of Object.entries(data.counts||{})){const node=$(`admin-${key}`);if(node)node.textContent=String(value)}$('tier-summary').textContent=(data.membersByTier||[]).map(row=>`${row.effective_tier}: ${row.count}`).join(' · ')||'No members';}
  async function loadMembers(query=''){const data=await api('/api/member/admin/members'+(query?`?q=${encodeURIComponent(query)}`:''));const body=$('member-rows');body.replaceChildren();if(!data.members.length)return empty(body,'No members matched.');for(const member of data.members){const tr=document.createElement('tr');tr.append(textCell(member.email),textCell(member.displayName),textCell(member.role),textCell(member.effectiveTier),textCell(member.status),textCell(member.activeSessions));body.append(tr)}}
  async function loadGrants(){const data=await api('/api/member/admin/grants');const body=$('grant-rows');body.replaceChildren();if(!data.grants.length)return empty(body,'No audited access grants.');for(const grant of data.grants){const tr=document.createElement('tr');tr.append(textCell(grant.email),textCell(grant.tier),textCell(grant.status),textCell(grant.reason),textCell(grant.expires_at||'No expiry'));const actions=document.createElement('td');if(grant.status==='active'){const button=document.createElement('button');button.className='btn danger';button.type='button';button.textContent='Revoke';button.addEventListener('click',async()=>{await api(`/api/member/admin/grants/${encodeURIComponent(grant.id)}`,{method:'DELETE'});await Promise.all([loadGrants(),loadSummary()])});actions.append(button)}tr.append(actions);body.append(tr)}}
  async function loadArchive(){const data=await api('/api/member/admin/archive');const body=$('archive-rows');body.replaceChildren();if(!data.entries.length)return empty(body,'No member archive entries.');for(const entry of data.entries){const tr=document.createElement('tr');tr.append(textCell(entry.title),textCell(entry.minimum_tier),textCell(entry.publication_status),textCell(entry.claim_class||''),textCell(entry.speculative_label||''));body.append(tr)}}
  async function loadDownloads(){const data=await api('/api/member/admin/downloads');const body=$('download-rows');body.replaceChildren();if(!data.downloads.length)return empty(body,'No protected downloads.');for(const item of data.downloads){const tr=document.createElement('tr');tr.append(textCell(item.title),textCell(item.minimum_tier),textCell(item.file_name),textCell(item.active?'Active':'Inactive'));body.append(tr)}}
  $('member-search').addEventListener('submit',event=>{event.preventDefault();loadMembers(new FormData(event.currentTarget).get('q')).catch(error=>status(error.message,'danger'))});
  $('grant-form').addEventListener('submit',async event=>{event.preventDefault();const data=new FormData(event.currentTarget);await api('/api/member/admin/grants',{method:'POST',body:{memberId:data.get('memberId'),tier:data.get('tier'),reason:data.get('reason'),expiresAt:data.get('expiresAt')||null}});event.currentTarget.reset();await Promise.all([loadGrants(),loadSummary()]);status('Audited access grant created.','good')});
  $('archive-form').addEventListener('submit',async event=>{event.preventDefault();const data=new FormData(event.currentTarget);await api('/api/member/admin/archive',{method:'POST',body:{canonicalId:data.get('canonicalId'),contentType:data.get('contentType'),title:data.get('title'),summary:data.get('summary'),route:data.get('route'),minimumTier:data.get('minimumTier'),claimClass:data.get('claimClass'),evidenceGrade:data.get('evidenceGrade'),speculativeLabel:data.get('speculativeLabel')||null,publicationStatus:'published'}});event.currentTarget.reset();await loadArchive();status('Archive entry saved.','good')});
  $('download-form').addEventListener('submit',async event=>{event.preventDefault();const data=new FormData(event.currentTarget);await api('/api/member/admin/downloads',{method:'POST',body:{title:data.get('title'),description:data.get('description'),storageKey:data.get('storageKey'),fileName:data.get('fileName'),mimeType:data.get('mimeType'),minimumTier:data.get('minimumTier'),productKey:data.get('productKey')||null}});event.currentTarget.reset();await loadDownloads();status('Protected download saved.','good')});
  (async()=>{try{status('Loading administrator controls…');await Promise.all([loadSummary(),loadMembers(),loadGrants(),loadArchive(),loadDownloads()]);$('admin-content').hidden=false;status('Administrator dashboard current.','good')}catch(error){status(error.message||'Administrator dashboard failed.','danger')}})();
})();
